dashboard.definition:
{
    "title": "Zentrale Notaufnahme",
    "description": "Notaufnahme: wartende Patientinnen und Patienten je Triage-Stufe, Wartezeiten, Zugaenge und Boarding",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Zeitraum",
            "options": {
                "token": "global_time",
                "defaultValue": "-4h@m,now"
            }
        },
        "input_triage": {
            "type": "input.dropdown",
            "title": "Triage-Stufe",
            "options": {
                "token": "triage",
                "defaultValue": "*",
                "items": [
                    {
                        "label": "Alle Stufen",
                        "value": "*"
                    },
                    {
                        "label": "1 sofort (rot)",
                        "value": "1"
                    },
                    {
                        "label": "2 sehr dringend (orange)",
                        "value": "2"
                    },
                    {
                        "label": "3 dringend (gelb)",
                        "value": "3"
                    },
                    {
                        "label": "4 normal (gruen)",
                        "value": "4"
                    },
                    {
                        "label": "5 nicht dringend (blau)",
                        "value": "5"
                    }
                ]
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        },
        "tokens": {
            "default": {
                "triage": {
                    "value": "*"
                }
            }
        }
    },
    "dataSources": {
        "ds_status": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:ed:tracking\" type=status | head 1\n| fields _time f longest_t1 longest_t2 longest_t3 longest_t4 longest_t5 longest_wait_min r status triage_level waiting waiting_t1 waiting_t2 waiting_t3 waiting_t4 waiting_t5",
                "enableSmartSources": true
            },
            "name": "Letzter Board-Status"
        },
        "ds_flow": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_status",
                "query": "| eval r=mvappend(\"1;\".waiting_t1.\";\".longest_t1, \"2;\".waiting_t2.\";\".longest_t2, \"3;\".waiting_t3.\";\".longest_t3, \"4;\".waiting_t4.\";\".longest_t4, \"5;\".waiting_t5.\";\".longest_t5)\n| mvexpand r\n| eval f=split(r, \";\"), triage_level=mvindex(f, 0), waiting=mvindex(f, 1), longest_wait_min=mvindex(f, 2)\n| table triage_level waiting longest_wait_min"
            }
        },
        "ds_k_status": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_status",
                "query": "| table status | rename status as Status"
            }
        },
        "ds_m": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_metrics metric_name IN (\"sakh.ed.waiting\", \"sakh.ed.boarding\", \"sakh.ed.longest_wait_min\", \"sakh.ed.door_to_doc_min\", \"sakh.ed.arrivals_per_hour\") BY metric_name span=10m",
                "enableSmartSources": true
            },
            "name": "Notaufnahme-Metriken"
        },
        "ds_k_wait": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_m",
                "query": "| where metric_name=\"sakh.ed.waiting\" | timechart span=10m avg(v) as Wartend"
            }
        },
        "ds_k_board": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_m",
                "query": "| where metric_name=\"sakh.ed.boarding\" | timechart span=10m avg(v) as Boarding"
            }
        },
        "ds_k_long": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_m",
                "query": "| where metric_name=\"sakh.ed.longest_wait_min\" | timechart span=10m avg(v) as \"Laengste Wartezeit\""
            }
        },
        "ds_k_d2d": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_m",
                "query": "| where metric_name=\"sakh.ed.door_to_doc_min\" | timechart span=10m avg(v) as \"Door-to-Doc\""
            }
        },
        "ds_k_arr": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_m",
                "query": "| where metric_name=\"sakh.ed.arrivals_per_hour\" | timechart span=10m avg(v) as \"Zugaenge/h\""
            }
        },
        "ds_trend": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_m",
                "query": "| where metric_name IN (\"sakh.ed.waiting\", \"sakh.ed.boarding\")\n| eval series=if(metric_name=\"sakh.ed.waiting\", \"Wartend\", \"Boarding (wartet auf Station)\")\n| timechart span=10m avg(v) by series"
            }
        },
        "ds_arrivals": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:ed:tracking\" type=arrival triage_level=\"$triage$\" | eval Stufe=triage_level.\" \".triage_label | timechart span=30m count by Stufe",
                "enableSmartSources": true
            },
            "name": "Zugaenge je Triage-Stufe"
        },
        "ds_complaints": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:ed:tracking\" type=arrival triage_level=\"$triage$\" | stats count as Zugaenge by complaint | sort - Zugaenge | head 10 | rename complaint as Leitsymptom",
                "enableSmartSources": true
            }
        },
        "ds_mode": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:ed:tracking\" type=arrival triage_level=\"$triage$\" | stats count by arrival_mode",
                "enableSmartSources": true
            }
        },
        "ds_target": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:ed:tracking\" type=arrival triage_level=\"$triage$\" | stats count as Zugaenge by target_department | sort - Zugaenge | rename target_department as Fachabteilung",
                "enableSmartSources": true
            }
        },
        "ds_last": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:ed:tracking\" type=arrival triage_level=\"$triage$\"\n| eval Zeit=strftime(_time, \"%H:%M\"), Triage=triage_level.\" \".triage_color\n| table Zeit Triage complaint target_department arrival_mode age sex\n| rename complaint as Leitsymptom target_department as Fachabteilung arrival_mode as Ankunft age as Alter sex as Geschlecht\n| head 50\n| appendpipe [| stats count | where count=0 | eval Zeit=\"Keine Zugaenge mit dieser Triage-Stufe im Zeitraum\" | fields - count]",
                "enableSmartSources": true
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
